  function passwordEyeIcon(parent, revealed = false, darkBg = false, targetKey = null) {
    const strokeHex = revealed ? (darkBg ? "#38BDF8" : "#1D4ED8") : (darkBg ? "#94A3B8" : "#475569");
    const btnBox = box(parent, "HORIZONTAL", {
      w: 34, h: 34, r: 8,
      fill: revealed ? (darkBg ? "color/primary" : "color/secondary-bg") : null,
      align: "CENTER", cross: "CENTER", to: targetKey,
    });
    const svg = revealed
      ? `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">` +
        `<path d="M9.88 9.88a3 3 0 1 0 4.24 4.24" stroke="${strokeHex}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>` +
        `<path d="M10.73 5.08A10.43 10.43 0 0 1 12 5c6.4 0 10 7 10 7a13.16 13.16 0 0 1-1.67 2.68" stroke="${strokeHex}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>` +
        `<path d="M6.61 6.61A13.526 13.526 0 0 0 2 12s3.6 7 10 7a9.74 9.74 0 0 0 5.39-1.61" stroke="${strokeHex}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>` +
        `<line x1="2" y1="2" x2="22" y2="22" stroke="${strokeHex}" stroke-width="2" stroke-linecap="round"/>` +
        `</svg>`
      : `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">` +
        `<path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7-10-7-10-7Z" stroke="${strokeHex}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>` +
        `<circle cx="12" cy="12" r="3" stroke="${strokeHex}" stroke-width="2"/>` +
        `</svg>`;
    try {
      const icon = figma.createNodeFromSvg(svg);
      icon.resize(18, 18);
      btnBox.appendChild(icon);
      try { icon.layoutSizingHorizontal = "FIXED"; icon.layoutSizingVertical = "FIXED"; } catch (_) {}
    } catch (_) {
      txt(btnBox, revealed ? "HIDE" : "SHOW", "FitSpace/Mono-Badge", darkBg ? "hud/primary" : "color/secondary");
    }
    return btnBox;
  }

  function passwordField(parent, width, label, valueText, revealed = false, darkBg = false, eyeTo = null) {
    const wrap = box(parent, "VERTICAL", { w: width, gap: 5 });
    txt(wrap, label, "FitSpace/Body-Small", darkBg ? "color/on-dark-body" : "color/text");
    const fld = box(wrap, "HORIZONTAL", {
      w: width, pl: 13, pr: 7, py: 5, r: 10,
      fill: darkBg ? "color/primary-elev" : "color/bg",
      stroke: revealed ? "color/secondary" : (darkBg ? "color/primary-border" : "color/border-strong"),
      sw: revealed ? 1.5 : 1,
      align: "SPACE_BETWEEN", cross: "CENTER",
    });
    txt(fld, valueText, "FitSpace/Body-Default", revealed ? (darkBg ? "color/on-dark" : "color/primary") : (darkBg ? "color/on-dark-muted" : "color/text-muted"));
    passwordEyeIcon(fld, revealed, darkBg, eyeTo);
    return wrap;
  }

  function qrGraphic(size, dark = false) {
    const bg = dark ? "#050A14" : "#FFFFFF";
    const border = dark ? "#38BDF8" : "#0B1120";
    const main = dark ? "#F8FAFC" : "#0B1120";
    const accent = dark ? "#38BDF8" : "#1D4ED8";
    const ok = dark ? "#4ADE80" : "#15803D";
    const svg =
      `<svg width="${size}" height="${size}" viewBox="0 0 108 108" fill="none" xmlns="http://www.w3.org/2000/svg">` +
      `<rect x="2" y="2" width="104" height="104" rx="14" fill="${bg}" stroke="${border}" stroke-width="2.5"/>` +
      `<rect x="14" y="14" width="24" height="24" rx="4" stroke="${main}" stroke-width="5"/>` +
      `<rect x="21" y="21" width="10" height="10" rx="1.5" fill="${accent}"/>` +
      `<rect x="70" y="14" width="24" height="24" rx="4" stroke="${main}" stroke-width="5"/>` +
      `<rect x="77" y="21" width="10" height="10" rx="1.5" fill="${accent}"/>` +
      `<rect x="14" y="70" width="24" height="24" rx="4" stroke="${main}" stroke-width="5"/>` +
      `<rect x="21" y="77" width="10" height="10" rx="1.5" fill="${accent}"/>` +
      `<rect x="48" y="48" width="12" height="12" rx="2" fill="${main}"/>` +
      `<rect x="66" y="48" width="10" height="10" rx="2" fill="${accent}"/>` +
      `<rect x="48" y="66" width="10" height="10" rx="2" fill="${accent}"/>` +
      `<rect x="68" y="70" width="22" height="9" rx="2" fill="${main}"/>` +
      `<rect x="78" y="84" width="14" height="10" rx="2" fill="${ok}"/>` +
      (dark ? `<line x1="12" y1="54" x2="96" y2="54" stroke="#4ADE80" stroke-width="2.5"/>` : "") +
      `</svg>`;
    try {
      const n = figma.createNodeFromSvg(svg);
      n.resize(size, size);
      return n;
    } catch (_) {
      const fallback = figma.createRectangle();
      fallback.resize(size, size);
      fallback.cornerRadius = 12;
      bindFill(fallback, dark ? "hud/surface" : "color/surface");
      bindStroke(fallback, dark ? "hud/primary" : "color/primary", 2);
      return fallback;
    }
  }

